mapper.select:
SELECT * FROM ( SELECT s.stock_code AS stockCode, s.stock_name AS stockName, s.market_type AS marketType, ( CASE WHEN UPPER(REGEXP_REPLACE(s.stock_name, '(보통주|[0-9]?우선주[A-Z]?)$', '')) LIKE UPPER(#{primaryKeyword}) || '%' THEN 80 WHEN UPPER(s.stock_name) LIKE UPPER(#{primaryKeyword}) || '%' THEN 70 WHEN UPPER(REGEXP_REPLACE(s.stock_name, '(보통주|[0-9]?우선주[A-Z]?)$', '')) LIKE '%' || UPPER(#{primaryKeyword}) || '%' THEN 50 WHEN UPPER(s.stock_name) LIKE '%' || UPPER(#{primaryKeyword}) || '%' THEN 40
WHEN UPPER(s.stock_code) LIKE '%' || UPPER(#{primaryKeyword}) || '%' THEN 30
ELSE 10 END + CASE WHEN s.stock_name LIKE '%보통주' THEN 15 ELSE 0 END
+ CASE
WHEN UPPER(REGEXP_REPLACE(s.stock_name, '(보통주|[0-9]?우선주[A-Z]?)$', '')) LIKE UPPER(#{bn}) || '%' THEN 60
ELSE 0 END
) AS matchScore, NVL(r.current_price * r.volume, 0) AS tradingValue FROM stocks s LEFT JOIN stock_realtime_current r ON s.stock_code = r.stock_code WHERE s.status = 'ACTIVE' AND (
s.stock_name LIKE '%' || #{kw} || '%' OR UPPER(s.stock_name) LIKE '%' || UPPER(#{kw}) || '%' OR REGEXP_REPLACE(s.stock_name, '(보통주|[0-9]?우선주[A-Z]?)$', '') LIKE '%' || #{kw} || '%' OR UPPER(REGEXP_REPLACE(s.stock_name, '(보통주|[0-9]?우선주[A-Z]?)$', '')) LIKE '%' || UPPER(#{kw}) || '%'
OR UPPER(s.stock_code) LIKE '%' || UPPER(#{kw}) || '%'
) ORDER BY matchScore DESC, tradingValue DESC, s.stock_name ) WHERE ROWNUM <= #{limit}
